files.content:
:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #a0a0b0;
  --border: #2a2a4a;
  --focus: #f5a623;
  --font: 'Courier New', Courier, monospace;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  background-image: linear-gradient(45deg, #15152a 25%, transparent 25%, transparent 75%, #15152a 75%),
                    linear-gradient(45deg, #15152a 25%, transparent 25%, transparent 75%, #15152a 75%);
  background-size: 32px 32px;
  background-position: 0 0, 16px 16px;
  font-family: var(--font);
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  width: 100%;
  max-width: 420px;
  background: var(--card-bg);
  border: 3px solid var(--border);
  border-radius: 4px;
  padding: 24px;
  box-shadow: 0 0 0 4px #0f0f1f, 8px 8px 0 0 #0f0f1f;
}

h1 {
  font-size: 1.25rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  text-align: center;
  color: var(--accent);
  margin-bottom: 4px;
}

.subtitle {
  text-align: center;
  font-size: 0.875rem;
  color: var(--muted);
  margin-bottom: 24px;
}

.field-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 16px;
}

label {
  font-size: 0.875rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--muted);
}

input, select {
  font-family: var(--font);
  font-size: 1rem;
  padding: 10px 12px;
  background: #0f0f1f;
  color: var(--text);
  border: 2px solid var(--border);
  border-radius: 2px;
  outline: none;
  transition: border-color 0.15s, box-shadow 0.15s;
}

input:hover, select:hover {
  border-color: var(--accent);
}

input:focus, select:focus {
  border-color: var(--focus);
  box-shadow: 0 0 0 3px rgba(245, 166, 35, 0.3);
}

.select-row {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: end;
  gap: 8px;
  margin-bottom: 16px;
}

.select-row .field-group {
  margin-bottom: 0;
}

.swap-btn {
  font-family: var(--font);
  font-size: 1.25rem;
  line-height: 1;
  padding: 10px 12px;
  background: var(--accent);
  color: #fff;
  border: 2px solid #b8304a;
  border-radius: 2px;
  cursor: pointer;
  transition: transform 0.1s, background 0.15s;
  margin-bottom: 2px;
}

.swap-btn:hover {
  background: #f05a72;
}

.swap-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.swap-btn:active {
  transform: translateY(2px);
  background: #b8304a;
}

.result {
  display: flex;
  align-items: baseline;
  justify-content: center;
  gap: 8px;
  padding: 20px;
  background: #0f0f1f;
  border: 2px dashed var(--border);
  border-radius: 2px;
  margin-top: 8px;
}

#result-value {
  font-size: 2rem;
  font-weight: bold;
  color: var(--accent);
  word-break: break-all;
}

#result-currency {
  font-size: 1rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 1px;
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
  }
  #result-value {
    font-size: 1.5rem;
  }
  .select-row {
    gap: 4px;
  }
  .swap-btn {
    padding: 10px 8px;
  }
}

(function () {
  'use strict';

  // Fixed built-in rates relative to USD (1 USD = X units)
  var RATES = {
    USD: 1,
    EUR: 0.92,
    JPY: 150.0,
    CNY: 7.2
  };

  var amountInput = document.getElementById('amount');
  var fromSelect = document.getElementById('from-currency');
  var toSelect = document.getElementById('to-currency');
  var swapBtn = document.getElementById('swap-btn');
  var resultValue = document.getElementById('result-value');
  var resultCurrency = document.getElementById('result-currency');

  function convert(amount, from, to) {
    if (!isFinite(amount) || amount < 0) return null;
    var usd = amount / RATES[from];
    return usd * RATES[to];
  }

  function update() {
    var raw = amountInput.value.trim();
    var amount = parseFloat(raw);
    var from = fromSelect.value;
    var to = toSelect.value;

    if (raw === '' || !isFinite(amount) || amount < 0) {
      resultValue.textContent = '0.00';
      resultCurrency.textContent = to;
      return;
    }

    var result = convert(amount, from, to);
    if (result === null || !isFinite(result)) {
      resultValue.textContent = '0.00';
    } else {
      resultValue.textContent = result.toFixed(2);
    }
    resultCurrency.textContent = to;
  }

  function swap() {
    var from = fromSelect.value;
    var to = toSelect.value;
    fromSelect.value = to;
    toSelect.value = from;
    update();
  }

  amountInput.addEventListener('input', update);
  fromSelect.addEventListener('change', update);
  toSelect.addEventListener('change', update);
  swapBtn.addEventListener('click', swap);

  // Prevent form submission on Enter
  document.getElementById('converter-form').addEventListener('submit', function (e) {
    e.preventDefault();
    update();
  });

  update();
})();
